style.css:
/* ? PINKIE PIE HOT PINK THEME ? */

:root {
    --pinkie-hot-pink: #ff1493;
    --pinkie-pink: #ff69b4;
    --pinkie-light: #ffb6d9;
    --pinkie-purple: #d8a5ff;
}

/* Background image + pink overlay */
html,
body {
    background-color: #ff69b4 !important;
    background-image:
        linear-gradient(
            rgba(255, 20, 147, 0.48),
            rgba(255, 105, 180, 0.48)
        ),
        url("https://i.imgur.com/6AOh1rp.png") !important;
    background-size: cover !important;
    background-position: center top !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
}

/* Pinkie Pie pink links */
a {
    color: #ff1493 !important;
}

a:hover {
    color: #d633ff !important;
}

/* Pink buttons */
button {
    border-color: #ff69b4 !important;
    border-radius: 12px !important;
}

/* Pink selection highlight */
::selection {
    background: #ff1493 !important;
    color: white !important;
}
